const recordServerHeartbeat = `-- name: RecordServerHeartbeat :one
WITH prev AS (
    SELECT p.id, p.status, p.proxy_status, p.proxy_error FROM servers p WHERE p.id = $4::uuid FOR UPDATE OF p
)
UPDATE servers s
SET status       = 'online',
    last_seen_at = now(),
    proxy_status = $1::text,
    proxy_error  = $2::text,
    facts        = CASE WHEN $3::text = '' THEN s.facts
                        ELSE jsonb_set(COALESCE(s.facts, '{}'::jsonb), '{dockerVersion}', to_jsonb($3::text)) END
FROM prev
WHERE s.id = prev.id AND s.status <> 'revoked'
RETURNING prev.status AS prev_status, prev.proxy_status AS prev_proxy_status, prev.proxy_error AS prev_proxy_error,
          s.workspace_id, s.name, s.disk_alert_threshold_percent, s.disk_alert_active
`

type RecordServerHeartbeatParams struct {
	ProxyStatus   string    `json:"proxyStatus"`
	ProxyError    string    `json:"proxyError"`
	DockerVersion string    `json:"dockerVersion"`
	ServerID      uuid.UUID `json:"serverId"`
}

type RecordServerHeartbeatRow struct {
	PrevStatus                string    `json:"prevStatus"`
	PrevProxyStatus           *string   `json:"prevProxyStatus"`
	PrevProxyError            *string   `json:"prevProxyError"`
	WorkspaceID               uuid.UUID `json:"workspaceId"`
	Name                      string    `json:"name"`
	DiskAlertThresholdPercent int32     `json:"diskAlertThresholdPercent"`
	DiskAlertActive           bool      `json:"diskAlertActive"`
}

// Returns the values from before the update so the caller can tell whether
// anything the UI shows has changed.
func (q *Queries) RecordServerHeartbeat(ctx context.Context, arg RecordServerHeartbeatParams) (RecordServerHeartbeatRow, error) {
	row := q.db.QueryRow(ctx, recordServerHeartbeat,
		arg.ProxyStatus,
		arg.ProxyError,
		arg.DockerVersion,
		arg.ServerID,
	)
	var i RecordServerHeartbeatRow
	err := row.Scan(
		&i.PrevStatus,
		&i.PrevProxyStatus,
		&i.PrevProxyError,
		&i.WorkspaceID,
		&i.Name,
		&i.DiskAlertThresholdPercent,
		&i.DiskAlertActive,
	)
	return i, err
}

